import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  OffsetFetch Request (Version: 3) => group_id [topics]
    group_id => STRING
    topics => name [partition_indexes]
      name => STRING
      partition_indexes => INT32
*/
export function createRequest(groups, _requireStable) {
    const group = groups[0] ?? { groupId: '', topics: null };
    return Writer.create()
        .appendString(group.groupId, false)
        .appendArray(group.topics, (writer, topic) => {
        writer
            .appendString(topic.name, false)
            .appendArray(topic.partitionIndexes, (writer, partitionIndex) => writer.appendInt32(partitionIndex), false, false);
    }, false, false);
}
/*
  OffsetFetch Response (Version: 3) => throttle_time_ms [topics] error_code
    throttle_time_ms => INT32
    topics => name [partitions]
      name => STRING
      partitions => partition_index committed_offset metadata error_code
        partition_index => INT32
        committed_offset => INT64
        metadata => NULLABLE_STRING
        error_code => INT16
    error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        topics: reader.readArray((topicReader, topicIndex) => ({
            name: topicReader.readString(false),
            partitions: topicReader.readArray((partitionReader, partitionIndex) => {
                const partition = {
                    partitionIndex: partitionReader.readInt32(),
                    committedOffset: partitionReader.readInt64(),
                    committedLeaderEpoch: -1,
                    metadata: partitionReader.readNullableString(false),
                    errorCode: partitionReader.readInt16()
                };
                if (partition.errorCode !== 0) {
                    errors.push([`/topics/${topicIndex}/partitions/${partitionIndex}`, [partition.errorCode, null]]);
                }
                return partition;
            }, false, false)
        }), false, false),
        errorCode: reader.readInt16(),
        groups: []
    };
    if (response.errorCode !== 0) {
        errors.push(['/errorCode', [response.errorCode, null]]);
    }
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(9, 3, createRequest, parseResponse, false, false);
